INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u04-l01','course-a1-foundations','my-day','My Day','Talk about a simple daily routine using common activity verbs.','A1',16,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u04-l01-q01','a1-u04-l01','multiple_choice','Complete: I ___ breakfast at seven.','[{"id":"a","text":"have"},{"id":"b","text":"has"},{"id":"c","text":"having"}]','a','Use have with I.',1),
('a1-u04-l01-q02','a1-u04-l01','multiple_choice','Which activity usually happens before breakfast?','[{"id":"a","text":"go to bed"},{"id":"b","text":"wake up"},{"id":"c","text":"come home"}]','b','Wake up commonly happens before breakfast.',2),
('a1-u04-l01-q03','a1-u04-l01','multiple_choice','Choose the correct sentence.','[{"id":"a","text":"I goes to school."},{"id":"b","text":"I go to school."},{"id":"c","text":"I going school."}]','b','Use the base verb with I.',3),
('a1-u04-l01-q04','a1-u04-l01','multiple_choice','Complete: I ___ home at five.','[{"id":"a","text":"come"},{"id":"b","text":"comes"},{"id":"c","text":"coming"}]','a','Use come with I.',4);
