INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u04-l02','course-a1-foundations','what-time-is-it','What Time Is It?','Understand and say common clock times using o''clock and quarter/half expressions.','A1',17,1,'published');
