('a1-u04-l02-q02','a1-u04-l02','multiple_choice','8:15 is ___.','[{"id":"a","text":"quarter to eight"},{"id":"b","text":"quarter past eight"},{"id":"c","text":"half past eight"}]','b','8:15 is fifteen minutes after eight.',2),
('a1-u04-l02-q03','a1-u04-l02','multiple_choice','9:45 is ___.','[{"id":"a","text":"quarter past nine"},{"id":"b","text":"half past nine"},{"id":"c","text":"quarter to ten"}]','c','9:45 is fifteen minutes before ten.',3),
