INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u04-l03','course-a1-foundations','a-busy-week','A Busy Week','Talk about days of the week and say when a routine happens.','A1',18,1,'published');
