INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u04-l05','course-a1-foundations','asking-about-routines','Asking About Routines','Ask and answer simple questions about another person''s daily schedule.','A1',20,1,'published');
