('a1-u04-l05-q01','a1-u04-l05','multiple_choice','Choose the correct question.','[{"id":"a","text":"What time do you get up?"},{"id":"b","text":"What time you get up?"},{"id":"c","text":"What time are you get up?"}]','a','Use What time + do + subject + base verb.',1),
('a1-u04-l05-q02','a1-u04-l05','multiple_choice','Choose the correct short answer: “Do you walk to school?”','[{"id":"a","text":"Yes, I do."},{"id":"b","text":"Yes, I am."},{"id":"c","text":"Yes, I walk do."}]','a','Use do in a short answer to a Do-question.',2),
('a1-u04-l05-q03','a1-u04-l05','multiple_choice','Complete: I go to bed ___ ten o''clock.','[{"id":"a","text":"on"},{"id":"b","text":"at"},{"id":"c","text":"in"}]','b','Use at with clock times.',3),
('a1-u04-l05-q04','a1-u04-l05','multiple_choice','Choose the correct sentence.','[{"id":"a","text":"What time does she start?"},{"id":"b","text":"What time does she starts?"},{"id":"c","text":"What time do she start?"}]','a','Use does + subject + base verb.',4);
